import React from 'react';
import { Header } from '../../../widgets/header';
import { Footer } from '../../../widgets/footer/ui/Footer';
import { BrandCard } from '../../../entities/brand/ui/BrandCard';
import { useNavigate } from 'react-router-dom';
import { Brand } from '../../../shared/types';
import './AllBrandsPage.css'

const allBrands: Brand[] = [];
// TODO: Загружать бренды с API

export const AllBrandsPage: React.FC = () => {
  const navigate = useNavigate();

  const handleBrandClick = (brand: Brand) => {
    // TODO: Реализовать навигацию по брендам когда они будут загружаться с API
    console.log('Brand clicked:', brand.name);
  };

  return (
    <>
      <Header title="БРЕНДЫ" subtitle="Все бренды в одном месте" />

      <main className="all-brands-content">
        <div className="brands-grid">
          {allBrands.map(brand => (
            <BrandCard 
              key={brand.id} 
              brand={brand} 
              onClick={() => handleBrandClick(brand)}
            />
          ))}
        </div>

        {allBrands.length === 0 && (
          <div className="empty-brands">
            <h2>Бренды временно недоступны</h2>
            <p>Загрузка брендов с API...</p>
          </div>
        )}
      </main>

      <Footer />
    </>
  );
};
